<script setup lang="ts">
import{ref,onMounted}from'vue';import{request,post}from'../api/client';import{ElMessageBox,ElMessage}from'element-plus';import{Upload,Setting,VideoPlay,Delete,Clock}from'@element-plus/icons-vue'
interface Field{key:string;label:string;type:string;required?:boolean;default?:string;options?:string[]}
interface Manifest{id:string;name:string;version:string;contractVersion:number;endpoint?:string;runtime?:string;settings?:Field[];capabilities:string[]}
interface Plugin{manifest:Manifest;enabled:boolean;builtin:boolean;revision:number;packageDigest?:string}
interface Package{manifest:Manifest;digest:string;files:string[];readme:string}
const items=ref<Plugin[]>([]),text=ref(''),busy=ref(false),error=ref(''),file=ref<File|null>(null),preview=ref<Package|null>(null),previewOpen=ref(false),configOpen=ref(false),selected=ref<Plugin|null>(null),values=ref<Record<string,string>>({}),secretFields=ref<string[]>([]),clearSecrets=ref<string[]>([]),configRevision=ref(0),testOpen=ref(false),filename=ref(''),result=ref<unknown>(null),runs=ref<Array<Record<string,unknown>>>([]),runsOpen=ref(false)
const isSecret=(f:Field)=>f.type==='password'||/(password|token|secret|api.?key|authorization|cookie)/i.test(f.key)
async function load(){try{items.value=await request('/plugins')}catch(e){error.value=e instanceof Error?e.message:'插件读取失败'}}
async function add(){busy.value=true;error.value='';try{const manifest=JSON.parse(text.value);await post('/plugins',{manifest,enabled:false,consent:false,revision:0});text.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Manifest无效'}finally{busy.value=false}}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;preview.value=null}
async function packageCall(install:boolean){if(!file.value)return;busy.value=true;error.value='';try{const form=new FormData();form.append('package',file.value);if(install&&preview.value){form.append('digest',preview.value.digest);form.append('confirm','true');form.append('revision',String(items.value.find(x=>x.manifest.id===preview.value?.manifest.id)?.revision??0))}const out=await request<Package>('/plugins/package'+(install?'':'?preview=true'),{method:'POST',body:form});if(install){previewOpen.value=false;preview.value=null;file.value=null;await load();ElMessage.success('插件包已安装，当前停用；升级后的设置需核对后重新启用。')}else{preview.value=out;previewOpen.value=true}}catch(e){error.value=e instanceof Error?e.message:'插件包无效'}finally{busy.value=false}}
async function toggle(item:Plugin){try{if(!item.enabled)await ElMessageBox.confirm(item.manifest.runtime==='rules'?'启用本地声明式规则？仅提供识别线索，不修改真实媒体。':`启用后向 ${item.manifest.endpoint} 发送识别/整理事件及本插件配置（可能包含你填写的插件凭据），不会获得系统其他服务密钥。是否授权？`,'启用插件',{type:'warning',confirmButtonText:'授权并启用',cancelButtonText:'取消'});await post('/plugins',{manifest:item.manifest,enabled:!item.enabled,consent:true,revision:item.revision});await load()}catch(e){if(e instanceof Error)error.value=e.message}}
async function configure(item:Plugin){selected.value=item;clearSecrets.value=[];try{const config=await request<{values:Record<string,string>;secretFields:string[];revision:number}>(`/plugins/${item.manifest.id}/settings`);values.value=config.values;secretFields.value=config.secretFields;configRevision.value=config.revision;for(const f of item.manifest.settings??[])if(values.value[f.key]===undefined)values.value[f.key]=isSecret(f)?'':f.default??'';configOpen.value=true}catch(e){error.value=e instanceof Error?e.message:'设置读取失败'}}
async function saveConfig(){if(!selected.value)return;busy.value=true;try{await request(`/plugins/${selected.value.manifest.id}/settings`,{method:'PUT',body:JSON.stringify({values:values.value,clear:clearSecrets.value,revision:configRevision.value})});configOpen.value=false;await load();ElMessage.success('配置已加密保存，插件已停用；确认新配置后重新启用。')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function remove(item:Plugin){try{await ElMessageBox.confirm(`卸载 ${item.manifest.name}？会删除插件设置和执行记录，不删除媒体。`,'卸载插件',{confirmButtonText:'确认卸载',cancelButtonText:'取消',type:'warning'})}catch{return};try{await request(`/plugins/${item.manifest.id}?confirm=true&revision=${item.revision}`,{method:'DELETE'});await load()}catch(e){error.value=e instanceof Error?e.message:'卸载失败'}}
async function test(){if(!selected.value)return;try{await ElMessageBox.confirm('执行一次明确的插件测试？远程插件会收到测试数据及本插件配置；不会修改真实媒体，也不会自动重试。','测试插件',{confirmButtonText:'确认测试',cancelButtonText:'取消'})}catch{return};busy.value=true;result.value=null;try{result.value=await post(`/plugins/${selected.value.manifest.id}/test`,{filename:filename.value,confirm:true})}catch(e){error.value=e instanceof Error?e.message:'测试失败'}finally{busy.value=false}}
async function history(item:Plugin){selected.value=item;try{runs.value=await request(`/plugins/${item.manifest.id}/runs`);runsOpen.value=true}catch(e){error.value=e instanceof Error?e.message:'记录读取失败'}}
onMounted(load)
</script>
<template><section class="page-heading"><div><span class="page-kicker">SYSTEM / 扩展</span><h1>插件扩展</h1><p>ZIP插件包 · 本地声明式规则 / HTTPS事件扩展 · 安装、设置、启停、升级、测试及卸载。</p></div><el-button @click="load">刷新插件</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<section class="panel section-gap"><div class="panel-title"><h2>安装 / 升级插件包</h2><span class="muted">ZIP ≤ 2 MiB · 解包 ≤ 4 MiB</span></div><p class="field-hint">根目录包含 manifest.json，可附 settings.json、rules.json、README.md。压缩包只读取声明，不解压到宿主、不执行未知代码；升级默认停用。旧版Manifest入口保留兼容。</p><div class="package-upload"><label for="plugin-package">选择ZIP插件包</label><input id="plugin-package" type="file" accept=".zip,application/zip" @change="pick"/><el-button :icon="Upload" type="primary" :loading="busy" :disabled="!file" @click="packageCall(false)">预览插件包</el-button></div></section>
<section class="plugin-grid"><article v-for="item in items" :key="item.manifest.id" class="panel"><div class="panel-title"><h2>{{item.manifest.name}}</h2><el-tag>{{item.builtin?'内置':item.enabled?'已启用':'停用'}}</el-tag></div><p class="muted">{{item.manifest.id}} · {{item.manifest.version}} · {{item.manifest.runtime==='rules'?'本地规则':item.builtin?'内置功能':'HTTPS扩展'}}</p><p>{{item.manifest.capabilities.join('、')}}</p><code v-if="item.manifest.endpoint">{{item.manifest.endpoint}}</code><p v-if="item.packageDigest" class="field-hint">已安装ZIP · {{item.packageDigest.slice(0,12)}}</p><div v-if="!item.builtin" class="plugin-actions"><el-button @click="toggle(item)">{{item.enabled?'停用扩展':'授权并启用'}}</el-button><el-button :icon="Setting" @click="configure(item)">设置</el-button><el-button :icon="VideoPlay" :disabled="!item.enabled" @click="selected=item;filename='';result=null;testOpen=true">测试</el-button><el-button :icon="Clock" @click="history(item)">记录</el-button><el-button :icon="Delete" type="danger" plain @click="remove(item)">卸载</el-button></div></article></section>
<details class="panel"><summary>兼容入口：导入扩展 Manifest</summary><p class="field-hint">新扩展默认停用。旧格式使用HTTPS事件Hook；本地规则须通过受支持的声明式合约。</p><el-input v-model="text" type="textarea" :rows="6" aria-label="插件Manifest"/><el-button type="primary" :loading="busy" :disabled="!text.trim()" @click="add">导入为停用插件</el-button></details>
<el-dialog v-model="previewOpen" title="插件包安装预览" width="min(760px,94vw)" :close-on-click-modal="false"><h2>{{preview?.manifest.name}} · {{preview?.manifest.version}}</h2><p class="field-hint">{{preview?.manifest.runtime==='rules'?'本地声明式识别规则':'HTTPS事件Hook'}} · {{preview?.manifest.capabilities.join('、')}}</p><code>{{preview?.digest}}</code><p>包含：{{preview?.files.join('、')}}</p><pre class="plugin-readme">{{preview?.readme||'没有附说明文档'}}</pre><p class="field-hint">安装/升级不会自动启用；如已有同ID插件，会保留兼容配置并停用。</p><template #footer><el-button @click="previewOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="packageCall(true)">确认安装或升级</el-button></template></el-dialog>
<el-dialog v-model="configOpen" :title="`${selected?.manifest.name} 插件设置`" width="min(650px,94vw)" :close-on-click-modal="false"><form class="connection-form" @submit.prevent="saveConfig"><template v-for="f in selected?.manifest.settings??[]" :key="f.key"><label :for="'plugin-setting-'+f.key">{{f.label}}{{f.required?'（必填）':''}}</label><el-select v-if="f.type==='select'" :id="'plugin-setting-'+f.key" v-model="values[f.key]"><el-option v-for="x in f.options" :key="x" :label="x" :value="x"/></el-select><el-select v-else-if="f.type==='boolean'" :id="'plugin-setting-'+f.key" v-model="values[f.key]"><el-option label="启用" value="true"/><el-option label="关闭" value="false"/></el-select><el-input v-else :id="'plugin-setting-'+f.key" v-model="values[f.key]" :type="isSecret(f)?'password':'text'" :show-password="isSecret(f)" :maxlength="2000" :autocomplete="isSecret(f)?'new-password':'off'" :placeholder="secretFields.includes(f.key)?'已设置；留空保持原值':''"/><el-checkbox v-if="isSecret(f)&&secretFields.includes(f.key)" v-model="clearSecrets" :value="f.key">明确清除 {{f.label}}</el-checkbox></template><p v-if="!selected?.manifest.settings?.length" class="field-hint">此插件没有自定义设置字段。</p><p class="field-hint">所有设置加密存储；秘密字段不自动回显。保存会停用插件，需核对后重新启用。</p><el-button type="primary" native-type="submit" :loading="busy">保存插件设置</el-button></form></el-dialog>
<el-dialog v-model="testOpen" title="测试插件（不修改媒体）" width="min(740px,94vw)"><label for="plugin-test-filename">测试文件名</label><el-input id="plugin-test-filename" v-model="filename" :maxlength="1024" placeholder="输入自有测试文件名，不选择真实文件"/><el-button :loading="busy" @click="test">执行测试</el-button><pre class="plugin-readme">{{result?JSON.stringify(result,null,2):'尚未运行测试'}}</pre></el-dialog>
<el-dialog v-model="runsOpen" title="插件最近执行记录" width="min(740px,94vw)"><el-table :data="runs" empty-text="暂无执行记录"><el-table-column prop="kind" label="事件"/><el-table-column prop="state" label="状态"/><el-table-column prop="message" label="提示"/><el-table-column prop="createdAt" label="时间"/></el-table></el-dialog>
</template>
<style scoped>.plugin-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin-bottom:24px}.plugin-grid p{margin:12px 0;line-height:1.7}.plugin-grid code{display:block;overflow-wrap:anywhere}.plugin-actions,.package-upload{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.plugin-actions .el-button+.el-button{margin-left:0}.package-upload input{max-width:100%}.plugin-readme{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;background:#151b23;color:#e5e9f0;padding:16px;border-radius:8px;line-height:1.8}.el-textarea{margin:16px 0}summary{cursor:pointer;font-size:14px;font-weight:600;min-height:44px}</style>
